import { create } from '@bufbuild/protobuf';
import { CascadeRequest } from '../cascade_request';
import { Err, Ok, Result } from '@archeglyph/proto/util/result';
import { FilteredAnnotation } from '../filtered_annotation';
import { FilteredDiagram } from '../filtered_diagram';
import { FilteredEdge } from '../filtered_edge';
import { FilteredGroup } from '../filtered_group';
import { FilteredNode } from '../filtered_node';
import {
  AnnotationEntry,
  CanvasStyleSchema,
  ColorSchema,
  EdgeStyleEntry,
  Fill,
  FillSchema,
  Glow,
  GlowSchema,
  Glyph1D,
  Glyph1DSchema,
  Glyph2D,
  Glyph2DSchema,
  GroupStyleEntry,
  NodeStyleEntry,
  Stroke,
  StrokeSchema,
  Stylesheet,
  Typography,
  TypographySchema,
} from '@archeglyph/proto/gen/style_pb';
import { AnnotationComponent, EdgeComponent, NodeComponent, Theme } from '@archeglyph/proto/gen/theme_pb';
import { ResolveError } from '../resolve_error';
import { ResolvedAnnotation } from '../resolved_annotation';
import { ResolvedDiagram } from '../resolved_diagram';
import { ResolvedEdge } from '../resolved_edge';
import { ResolvedGroup } from '../resolved_group';
import { ResolvedNode } from '../resolved_node';
import { StyleCascade } from './schema_gen';
import { init } from '@archeglyph/proto/util/init';

function compareIds(a: string, b: string): number {
  if (a < b) { return -1; } else if (a > b) { return 1; } else { return 0; }
}

function mergeStroke(base: Stroke, layer: Stroke): void {
  if (layer.paint.case !== undefined) { base.paint = layer.paint; }
  if (layer.width !== undefined) { base.width = layer.width; }
  if (layer.dashing.case !== undefined) { base.dashing = layer.dashing; }
  if (layer.cap !== undefined) { base.cap = layer.cap; }
  if (layer.join !== undefined) { base.join = layer.join; }
}

function mergeFill(base: Fill, layer: Fill): void {
  if (layer.paint.case !== undefined) { base.paint = layer.paint; }
  if (layer.opacity !== undefined) { base.opacity = layer.opacity; }
}

function mergeGlow(base: Glow, layer: Glow): void {
  if (layer.color !== undefined) { base.color = layer.color; }
  if (layer.radius !== undefined) { base.radius = layer.radius; }
  if (layer.intensity !== undefined) { base.intensity = layer.intensity; }
}

function mergeGlyph2D(base: Glyph2D, layer: Glyph2D): void {
  if (layer.shapeKind.case !== undefined) { base.shapeKind = layer.shapeKind; }
  if (layer.cornerRadius !== undefined) { base.cornerRadius = layer.cornerRadius; }
  if (layer.stroke !== undefined) {
    if (base.stroke === undefined) { base.stroke = create(StrokeSchema); }
    mergeStroke(base.stroke, layer.stroke);
  }
  if (layer.fill !== undefined) {
    if (base.fill === undefined) { base.fill = create(FillSchema); }
    mergeFill(base.fill, layer.fill);
  }
  if (layer.glow !== undefined) {
    if (base.glow === undefined) { base.glow = create(GlowSchema); }
    mergeGlow(base.glow, layer.glow);
  }
  if (layer.decorations.length > 0) { base.decorations = layer.decorations.slice(); }
}

function mergeGlyph1D(base: Glyph1D, layer: Glyph1D): void {
  if (layer.stroke !== undefined) {
    if (base.stroke === undefined) { base.stroke = create(StrokeSchema); }
    mergeStroke(base.stroke, layer.stroke);
  }
  if (layer.arrowheads !== undefined) { base.arrowheads = layer.arrowheads; }
  if (layer.glow !== undefined) {
    if (base.glow === undefined) { base.glow = create(GlowSchema); }
    mergeGlow(base.glow, layer.glow);
  }
}

function mergeTypography(base: Typography, layer: Typography): void {
  if (layer.font !== undefined) { base.font = layer.font; }
  if (layer.color !== undefined) { base.color = layer.color; }
  if (layer.size !== undefined) { base.size = layer.size; }
  if (layer.weight !== undefined) { base.weight = layer.weight; }
  if (layer.align !== undefined) { base.align = layer.align; }
  if (layer.visible !== undefined) { base.visible = layer.visible; }
  if (layer.background !== undefined) { base.background = layer.background; }
}

// An unqualified name binds to `default`, which is why every existing
// stylesheet keeps working without a prefix.
export function splitQualified(name: string): { theme: string; component: string } {
  const dot = name.indexOf('.');
  return dot < 0
    ? { theme: 'default', component: name }
    : { theme: name.slice(0, dot), component: name.slice(dot + 1) };
}

type Finder<T> = (theme: Theme, component: string) => T | undefined;

// Returns the component, or the reason it could not be found, so the caller
// can say which theme it looked in rather than only which name was missing.
function findComponent<T>(
  themes: ReadonlyMap<string, Theme> | undefined,
  qualified: string,
  pick: Finder<T>,
): { found: T } | { error: string } {
  const { theme: themeName, component } = splitQualified(qualified);
  const theme = themes?.get(themeName);
  if (theme === undefined) {
    return { error: `no theme bound to '${themeName}'` };
  }
  const found = pick(theme, component);
  return found === undefined
    ? { error: `component '${component}' not found in theme '${themeName}'` }
    : { found };
}

const pickNode: Finder<NodeComponent> = (t, n) => t.nodeComponents.find((c: NodeComponent): boolean => c.name === n);
const pickEdge: Finder<EdgeComponent> = (t, n) => t.edgeComponents.find((c: EdgeComponent): boolean => c.name === n);
const pickGroup: Finder<NodeComponent> = (t, n) => t.groupComponents.find((c: NodeComponent): boolean => c.name === n);
const pickAnnotation: Finder<AnnotationComponent> = (t, n) => t.annotationComponents.find((c: AnnotationComponent): boolean => c.name === n);

/**
 * The component name to look up: the entry's own, else the theme's stated
 * default for this element type.
 *
 * The fallback is what lets a style entry leave `component` empty, and an
 * empty value is the only thing that means nobody chose. Seeding used to
 * write the default in instead, which made a seeded value indistinguishable
 * from one a user typed -- so `bind --component <the default>` was silently
 * rewritten on the next load.
 *
 * The theme names the component; the resolver never invents one. A theme
 * stating no default leaves unbound elements unstyled, per design.md §5.
 */
function componentNameFor(explicit: string | undefined, themeDefault: string | undefined): string | undefined {
  if (explicit !== undefined && explicit !== '') return explicit;
  return themeDefault !== undefined && themeDefault !== '' ? themeDefault : undefined;
}

export class StyleCascadeImpl implements StyleCascade {
  cascade(request: CascadeRequest): Result<ResolvedDiagram, ResolveError> {
    const filtered: FilteredDiagram = request.filtered;
    const stylesheet: Stylesheet | undefined = request.stylesheet;
    const themes: ReadonlyMap<string, Theme> | undefined = request.themes;

    // Absent means transparent, not an error: this lookup is the engine's,
    // not the author's. A '$palette.x' value is chased by the token resolver.
    const canvas = create(CanvasStyleSchema, stylesheet?.canvas ?? {});
    const themeBackground: string | undefined = themes?.get('default')?.tokens?.roles['background'];
    if (canvas.background === undefined && themeBackground !== undefined) {
      canvas.background = create(ColorSchema, { value: themeBackground });
    }
    const result: ResolvedDiagram = init(new ResolvedDiagram(), {
      id: filtered.id,
      canvas,
    });

    const sortedNodes: FilteredNode[] = Object.values(filtered.nodes);
    sortedNodes.sort((a: FilteredNode, b: FilteredNode): number => compareIds(a.id, b.id));
    for (const node of sortedNodes) {
      const entry: NodeStyleEntry | undefined = stylesheet?.nodes[node.id];
      const componentName: string | undefined = componentNameFor(entry?.component, themes?.get('default')?.defaultNodeComponent);
      let themeComponent: NodeComponent | undefined;
      if (componentName !== undefined) {
        const looked = findComponent(themes, componentName, pickNode);
        if ('error' in looked) {
          return Err(init(new ResolveError(), { message: `node ${node.id}: ${looked.error}` }));
        }
        themeComponent = looked.found;
      }
      const shape: Glyph2D = create(Glyph2DSchema);
      if (themeComponent?.shape !== undefined) { mergeGlyph2D(shape, themeComponent.shape); }
      if (entry?.shape !== undefined) { mergeGlyph2D(shape, entry.shape); }
      const typography: Typography = create(TypographySchema);
      if (themeComponent?.typography !== undefined) { mergeTypography(typography, themeComponent.typography); }
      if (entry?.typography !== undefined) { mergeTypography(typography, entry.typography); }
      const resolved: ResolvedNode = init(new ResolvedNode(), {
        id: node.id,
        parentGroup: node.parentGroup,
        shape,
        typography,
        layout: entry?.layout,
        label: node.label,
      });
      result.nodes[node.id] = resolved;
    }

    const sortedEdges: FilteredEdge[] = Object.values(filtered.edges);
    sortedEdges.sort((a: FilteredEdge, b: FilteredEdge): number => compareIds(a.id, b.id));
    for (const edge of sortedEdges) {
      const entry: EdgeStyleEntry | undefined = stylesheet?.edges[edge.id];
      const componentName: string | undefined = componentNameFor(entry?.component, themes?.get('default')?.defaultEdgeComponent);
      let themeComponent: EdgeComponent | undefined;
      if (componentName !== undefined) {
        const looked = findComponent(themes, componentName, pickEdge);
        if ('error' in looked) {
          return Err(init(new ResolveError(), { message: `edge ${edge.id}: ${looked.error}` }));
        }
        themeComponent = looked.found;
      }
      const connection: Glyph1D = create(Glyph1DSchema);
      if (themeComponent?.connection !== undefined) { mergeGlyph1D(connection, themeComponent.connection); }
      if (entry?.connection !== undefined) { mergeGlyph1D(connection, entry.connection); }
      const typography: Typography = create(TypographySchema);
      if (themeComponent?.typography !== undefined) { mergeTypography(typography, themeComponent.typography); }
      if (entry?.typography !== undefined) { mergeTypography(typography, entry.typography); }
      const resolved: ResolvedEdge = init(new ResolvedEdge(), {
        id: edge.id,
        source: edge.source,
        target: edge.target,
        connection,
        typography,
        layout: entry?.layout,
        label: edge.label,
      });
      result.edges[edge.id] = resolved;
    }

    const sortedGroups: FilteredGroup[] = Object.values(filtered.groups);
    sortedGroups.sort((a: FilteredGroup, b: FilteredGroup): number => compareIds(a.id, b.id));
    for (const group of sortedGroups) {
      const entry: GroupStyleEntry | undefined = stylesheet?.groups[group.id];
      const componentName: string | undefined = componentNameFor(entry?.component, themes?.get('default')?.defaultGroupComponent);
      let themeComponent: NodeComponent | undefined;
      if (componentName !== undefined) {
        const looked = findComponent(themes, componentName, pickGroup);
        if ('error' in looked) {
          return Err(init(new ResolveError(), { message: `group ${group.id}: ${looked.error}` }));
        }
        themeComponent = looked.found;
      }
      const shape: Glyph2D = create(Glyph2DSchema);
      if (themeComponent?.shape !== undefined) { mergeGlyph2D(shape, themeComponent.shape); }
      if (entry?.shape !== undefined) { mergeGlyph2D(shape, entry.shape); }
      const typography: Typography = create(TypographySchema);
      if (themeComponent?.typography !== undefined) { mergeTypography(typography, themeComponent.typography); }
      if (entry?.typography !== undefined) { mergeTypography(typography, entry.typography); }
      const resolved: ResolvedGroup = init(new ResolvedGroup(), {
        id: group.id,
        parentGroup: group.parentGroup,
        shape,
        typography,
        layout: entry?.layout,
        label: group.label,
        isSuperNode: group.isSuperNode,
        hiddenDescendantCount: group.hiddenDescendantCount,
      });
      result.groups[group.id] = resolved;
    }

    const sortedAnnotations: FilteredAnnotation[] = Object.values(filtered.annotations);
    sortedAnnotations.sort((a: FilteredAnnotation, b: FilteredAnnotation): number => compareIds(a.id, b.id));
    for (const annotation of sortedAnnotations) {
      const entry: AnnotationEntry = annotation.entry;
      const componentName: string | undefined = componentNameFor(entry.component, themes?.get('default')?.defaultAnnotationComponent);
      let themeComponent: AnnotationComponent | undefined;
      if (componentName !== undefined) {
        const looked = findComponent(themes, componentName, pickAnnotation);
        if ('error' in looked) {
          return Err(init(new ResolveError(), { message: `annotation ${annotation.id}: ${looked.error}` }));
        }
        themeComponent = looked.found;
      }
      const shape: Glyph2D = create(Glyph2DSchema);
      if (themeComponent?.shape !== undefined) { mergeGlyph2D(shape, themeComponent.shape); }
      if (entry.shape !== undefined) { mergeGlyph2D(shape, entry.shape); }
      const typography: Typography = create(TypographySchema);
      if (themeComponent?.typography !== undefined) { mergeTypography(typography, themeComponent.typography); }
      if (entry.typography !== undefined) { mergeTypography(typography, entry.typography); }
      const callout: Glyph1D = create(Glyph1DSchema);
      if (entry.anchor !== undefined) {
        if (themeComponent?.callout !== undefined) { mergeGlyph1D(callout, themeComponent.callout); }
        if (entry.callout !== undefined) { mergeGlyph1D(callout, entry.callout); }
      }
      const resolved: ResolvedAnnotation = init(new ResolvedAnnotation(), {
        id: annotation.id,
        anchor: entry.anchor,
        shape,
        typography,
        callout,
        layout: entry.layout,
        content: entry.content,
      });
      result.annotations[annotation.id] = resolved;
    }

    return Ok(result);
  }
}
